package org.apache.commons.compress.archivers.tar;

import java.io.*;
import java.math.*;
import java.util.*;
import org.junit.*;
import org.junit.Test;
import static org.junit.Assert.*;
import static org.junit.Assert.assertEquals;

/**
 * Unit tests for TarUtils.computeCheckSum
 */
public class TarUtils_computeCheckSum_TriageGen0Test {





    @Test
    public void testComputeCheckSum_SingleNegativeByte() {
        // In Java, bytes are signed. 0xFF is -1. 
        // The method uses BYTE_MASK (0xFF) to treat it as unsigned.
        // -1 & 0xFF = 255
        byte[] buf = new byte[]{(byte) 0xFF};
        long expected = 255L;
        long actual = TarUtils.computeCheckSum(buf);
        assertEquals("Checksum calculation failed for negative byte (should be treated as unsigned)", expected, actual);
    }






}

package org.apache.commons.compress.archivers.tar;

import java.io.*;
import java.math.*;
import java.util.*;
import org.junit.*;
import org.junit.Test;
import static org.junit.Assert.*;
import static org.junit.Assert.assertEquals;

/**
 * Unit tests for TarUtils.computeCheckSum
 */
public class TarUtils_computeCheckSum_TriageGen0Test {







    @Test
    public void testComputeCheckSum_MultipleBytes() {
        // 0x01 + 0x02 + 0x7F + 0xFF (as unsigned)
        // 1 + 2 + 127 + 255 = 385
        byte[] buf = new byte[]{0x01, 0x02, 0x7F, (byte) 0xFF};
        long expected = 385L;
        long actual = TarUtils.computeCheckSum(buf);
        assertEquals("Checksum calculation failed for multiple bytes", expected, actual);
    }




}

