package org.apache.commons.compress.archivers.tar;

import java.io.*;
import java.math.*;
import java.util.*;
import org.junit.*;
import org.junit.Test;
import static org.junit.Assert.*;
import static org.junit.Assert.assertEquals;

/**
 * Unit tests for TarUtils.computeCheckSum
 */
public class TarUtils_computeCheckSum_TriageGen0Test {











    @Test
    public void testComputeCheckSum_LargeValues() {
        // Test to ensure long return type handles accumulation
        // 255 * 10 = 2550
        byte[] buf = new byte[10];
        for (int i = 0; i < 10; i++) {
            buf[i] = (byte) 0xFF;
        }
        long expected = 2550L;
        long actual = TarUtils.computeCheckSum(buf);
        assertEquals("Checksum failed for large accumulation", expected, actual);
    }
}
